import subprocess
def rc(s):
    c={'a':'t','t':'a','g':'c','c':'g'}; return ''.join(c[x] for x in reversed(s))
seqs={}; name=None
for line in open('/app/sequences.fasta'):
    line=line.strip()
    if not line: continue
    if line.startswith('>'): name=line[1:]; seqs[name]=''
    else: seqs[name]+=line.lower()
inp=seqs['input']; egfp=seqs['egfp']; flag=seqs['flag']; snap=seqs['snap']
FLAGS=['-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500']
def tm(s):
    r=subprocess.run(['oligotm']+FLAGS+[s.upper()],capture_output=True,text=True)
    return float(r.stdout.strip())
# annealing sequence generators
anneal={
 'egfp':(lambda L: egfp[0:L], lambda L: rc(egfp[714-L:714])),
 'flag':(lambda L: flag[3:3+L], lambda L: rc(flag[87-L:87])),
 'snap':(lambda L: snap[3:3+L], lambda L: rc(snap[549-L:549])),
 'input':(lambda L: inp[690:690+L], lambda L: rc(inp[210-L:210])),
}
# for each fragment build Tm tables
best={}
for frag,(fF,fR) in anneal.items():
    tblF={}; tblR={}
    for L in range(15,37):
        sf=fF(L); sr=fR(L)
        if len(sf)==L: tblF[L]=(sf,tm(sf))
        if len(sr)==L: tblR[L]=(sr,tm(sr))
    # choose pair: both Tm in [58,72], |diff|<=5, prefer shorter, minimize diff
    cand=[]
    for lf,(sf,tf) in tblF.items():
        for lr,(sr,tr) in tblR.items():
            if 58<=tf<=72 and 58<=tr<=72 and abs(tf-tr)<=5:
                cand.append((abs(tf-tr),lf+lr,lf,lr,sf,tf,sr,tr))
    cand.sort()
    d,tot,lf,lr,sf,tf,sr,tr=cand[0]
    best[frag]=(sf,tf,sr,tr)
    print(frag,'FWD',sf,round(tf,2),'REV',sr,round(tr,2),'diff',round(abs(tf-tr),2))
import json
json.dump({k:(v[0],v[2]) for k,v in best.items()},open('/app/best.json','w'))
